                    autoStartReworkConfigFile: 'agents/pr_test_automation_rework.json'
                }
            }
        }
    };
    var scm = options.scm || {
        getRemoteRepoInfo: function() { return { owner: 'IstiN', repo: 'trackstate' }; },
        listPrs: function() {
            return [{
