        console.log('  ' + (cfg.dryRun ? '[dry] ' : '') + '▶️  gh-' + issue.number + ' ' +
            a.type + (a.leg ? ':' + a.leg : '') + ' — ' + a.reason);
        if (cfg.dryRun) { counters.acted++; if (a.type === 'dispatch') counters.dispatched++; return; }
        try {
