    var counters = { acted: 0, dispatched: 0, skipped: 0, failures: 0 };
    var prRef = provider.findPr(issue.number, cfg.branchPrefix);
    var pr = prRef && prRef.state === 'OPEN' ? provider.prStatus(prRef.number) : prRef;
    var state = {
