        a.headSha = (pr && pr.headSha) || null;
        console.log('  ' + (cfg.dryRun ? '[dry] ' : '') + '▶️  gh-' + issue.number + ' ' +
            a.type + (a.leg ? ':' + a.leg : '') + ' — ' + a.reason);
