+    // left (jira.stageFallback 'label'); 'none' mode compares the status only.
+    var wasReviewPassed = getTracker().hasStage(ticketDetail, 'IN_REVIEW_PASSED', jiraConfig.statuses.IN_REVIEW_PASSED);
